// ── Limit logic: Claro/Box groups allow 6, others 5 ──────────
function getGroupLimit(groupName) {
  if (!groupName) return 5;
  const n = groupName.toLowerCase();
  if (n.includes("claro") || n.includes("box")) return 6;
  return 5; // streaming também é 5
}

function getGroupType(groupName) {
  if (!groupName) return "padrao";
  const n = groupName.toLowerCase();
  if (n.includes("streaming")) return "streaming";
  if (n.includes("claro")) return "claro";
  if (n.includes("box")) return "box";
  return "padrao";
}

