function getPayStatus(client, month) {
  const p = client.payments?.[month];
  if (p) {
    const st = typeof p === "string" ? p : p.status || "pendente";
    // parcial: só retorna parcial se ainda há saldo restante
    if (st === "pago") return "pago";
    if (st === "parcial") {
      const paid = typeof p === "object" ? p.paid || 0 : 0;
      if (paid >= (client.monthlyValue || 0)) return "pago";
      return "parcial";
    }
  }
  const [year, mon] = month.split("-").map(Number);
  const dueDay = parseInt(client.dueDate) || 1;
  // último dia do mês caso dueDay > dias do mês
  const dim = new Date(year, mon, 0).getDate();
  const safeDue = Math.min(dueDay, dim);
  const dueDate = new Date(year, mon - 1, safeDue);
  dueDate.setHours(23, 59, 59, 999); // vence no final do dia, não no início
  const now = new Date();
  return now > dueDate ? "atrasado" : "pendente";
}
function getPayObj(client, month) {
  const p = client.payments?.[month];
  if (!p) return null;
  if (typeof p === "string") {
    return {
      status: p,
      paid: p === "pago" ? client.monthlyValue || 0 : 0,
      date: "",
      remaining: p === "pago" ? 0 : client.monthlyValue || 0,
    };
  }
  // garante que remaining seja sempre calculado corretamente
  const paid = p.paid || 0;
  const remaining =
    p.remaining != null
      ? p.remaining
      : Math.max(0, (client.monthlyValue || 0) - paid);
  return { ...p, paid, remaining };
}
function sendCobranca(c, month) {
  const ph = (c.phone || "").replace(/\D/g, "");
  if (!ph) {
    alert("Telefone não cadastrado!");
    return;
  }
  const msg = encodeURIComponent(
    `Olá, *${c.name}*! 👋\n\nSua mensalidade OI TV de *${fmtMonth(month)}* no valor de *${fmtMoney(c.monthlyValue)}* está em aberto.\n\nPor favor, pague até o dia *${c.dueDate}*.\n\nObrigado! 😊`,
  );
  window.open(`https://wa.me/55${ph}?text=${msg}`, "_blank");
}

