function PaymentModal({ client, month, onSave, onClose, C }) {
  const existing = getPayObj(client, month);
  const [paid, setPaid] = useState(String(existing?.paid ?? ""));
  const [date, setDate] = useState(existing?.date || today());
  const [notes, setNotes] = useState(existing?.notes || "");
  const paidNum = parseFloat(paid) || 0;
  const totalValue = client.monthlyValue || 0;
  const remaining = Math.max(0, totalValue - paidNum);
  const paidPct =
    totalValue > 0
      ? Math.min(100, Math.round((paidNum / totalValue) * 100))
      : 0;
  const status =
    paidNum <= 0 ? "pendente" : paidNum >= totalValue ? "pago" : "parcial";
  return (
    <Modal
      title="💳 Registrar Pagamento"
      onClose={onClose}
      maxWidth={500}
      C={C}
    >
      <div
        style={{
          background: C.inputBg,
          borderRadius: 14,
          padding: "16px 20px",
          marginBottom: 22,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          border: `1px solid ${C.border}`,
        }}
      >
        <div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.text }}>
            {client.name}
          </div>
          <div style={{ fontSize: 12, color: C.muted, marginTop: 2 }}>
            Vencimento: dia {client.dueDate} · {fmtMonth(month)}
          </div>
        </div>
        <StatusBadge status={status} C={C} />
      </div>
      <Field
        label={`Valor Pago (Total: ${fmtMoney(totalValue)})`}
        type="number"
        placeholder="0,00"
        value={paid}
        onChange={(e) => setPaid(e.target.value)}
        C={C}
      />
      <div style={{ marginBottom: 18 }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginBottom: 8,
          }}
        >
          <span style={{ fontSize: 13, fontWeight: 600, color: C.muted }}>
            Progresso
          </span>
          <span style={{ fontSize: 13, fontWeight: 700, color: C.primary }}>
            {paidPct}%
          </span>
        </div>
        <div
          style={{
            background: C.border,
            borderRadius: 99,
            height: 8,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              width: `${paidPct}%`,
              height: "100%",
              background: status === "pago" ? G.success : C.gradientPrimary,
              borderRadius: 99,
              transition: "width 0.6s",
            }}
          />
        </div>
      </div>
      {remaining === 0 && paidNum > 0 && (
        <div
          style={{
            padding: "10px 14px",
            background: C.successLight,
            borderRadius: 10,
            marginBottom: 14,
            fontSize: 13,
            color: C.successDark,
            fontWeight: 700,
          }}
        >
          ✅ Quitado!
        </div>
      )}
      {remaining > 0 && paidNum > 0 && (
        <div
          style={{
            padding: "10px 14px",
            background: C.dangerLight,
            borderRadius: 10,
            marginBottom: 14,
            fontSize: 13,
            color: C.dangerDark,
            fontWeight: 600,
          }}
        >
          ⚠️ Restante: {fmtMoney(remaining)}
        </div>
      )}
      <Field
        label="Data do Pagamento"
        type="date"
        value={date}
        onChange={(e) => setDate(e.target.value)}
        C={C}
      />
      <div style={{ marginBottom: 20 }}>
        <label
          style={{
            display: "block",
            marginBottom: 6,
            fontSize: 13,
            fontWeight: 600,
            color: C.text,
          }}
        >
          Observações
        </label>
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={2}
          className="rb-input"
          style={{
            width: "100%",
            padding: "11px 14px",
            border: `1.5px solid ${C.border}`,
            borderRadius: 10,
            fontSize: 13,
            boxSizing: "border-box",
            resize: "vertical",
            fontFamily: "inherit",
            background: C.inputBg,
            color: C.text,
          }}
        />
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
        <Btn variant="secondary" onClick={onClose} C={C}>
          Cancelar
        </Btn>
        <Btn
          variant="success"
          onClick={() =>
            onSave({ status, paid: paidNum, remaining, date, notes })
          }
          C={C}
        >
          ✅ Salvar
        </Btn>
      </div>
    </Modal>
  );
}

