                          padding: "12px 16px",
                          textAlign: "left",
                          fontSize: 10,
                          fontWeight: 700,
                          color: C.muted,
                          borderBottom: `1px solid ${C.border}`,
                          textTransform: "uppercase",
                          whiteSpace: "nowrap",
