  function abrirCaixa() {
    if (!saldoInicial && saldoInicial !== "0")
      return alert("Informe o saldo inicial (pode ser 0).");
    const sessao = {
      id: Date.now(),
      status: "aberto",
      dataAbertura: today(),
      horaAbertura: new Date().toLocaleTimeString("pt-BR", {
        hour: "2-digit",
        minute: "2-digit",
      }),
      saldoInicial: parseFloat(saldoInicial) || 0,
      obsAbertura,
      operador: "Admin",
      vendas: [],
    };
    saveSessoes((p) => [sessao, ...p]);
    setSaldoInicial("");
    setObsAbertura("");
    setShowAbrirModal(false);
  }

  function fecharCaixa() {
    if (!sessaoAtiva) return;
    // vendas desta sessão (do dia de abertura)
    const vendasSessao = vendas.filter(
      (v) => v.date === sessaoAtiva.dataAbertura,
    );
    const totalVendas = vendasSessao.reduce((s, v) => s + v.total, 0);
    const totalLucro = vendasSessao.reduce((s, v) => s + (v.lucro || 0), 0);
    const byPayS = Object.keys(CAIXA_PAY).reduce((acc, k) => {
      acc[k] = vendasSessao
        .filter((v) => v.paymentMethod === k)
        .reduce((s, v) => s + v.total, 0);
      return acc;
    }, {});
    const saldoFinal = (sessaoAtiva.saldoInicial || 0) + totalVendas;
    const conf = {};
    Object.keys(CAIXA_PAY).forEach((k) => {
      conf[k] = parseFloat(conferenciaValores[k]) || 0;
    });
    const diffDinheiro =
      (conf.dinheiro || 0) -
      ((byPayS.dinheiro || 0) + (sessaoAtiva.saldoInicial || 0));

    const sessaoFechada = {
      ...sessaoAtiva,
      status: "fechado",
      dataFechamento: today(),
      horaFechamento: new Date().toLocaleTimeString("pt-BR", {
        hour: "2-digit",
        minute: "2-digit",
      }),
      totalVendas,
      totalLucro,
      saldoFinal,
      byPay: byPayS,
      conferenciaValores: conf,
      diffDinheiro,
      qtdVendas: vendasSessao.length,
      obsFechamento,
    };
    saveSessoes((p) =>
      p.map((s) => (s.id === sessaoAtiva.id ? sessaoFechada : s)),
    );
    setConferenciaValores({
      dinheiro: "",
      pix: "",
      credito: "",
      debito: "",
      promissoria: "",
    });
    setObsFechamento("");
    setShowFecharModal(false);
    setShowFechamentoPDF(sessaoFechada);
  }

