function PDVBackupBtn({ onBackup, hasUnsaved }) {
  const [hov, setHov] = useState(false);
  const [done, setDone] = useState(false);
  function handleClick() {
    onBackup();
    setDone(true);
    setTimeout(() => setDone(false), 2500);
  }
  return (
    <button
      onMouseEnter={() => setHov(true)}
      onMouseLeave={() => setHov(false)}
      onClick={handleClick}
      title="Fazer backup agora"
      style={{
        background: done
          ? "rgba(16,185,129,.25)"
          : hov
            ? "rgba(245,158,11,.25)"
            : "rgba(245,158,11,.12)",
        border: `1px solid ${done ? "rgba(16,185,129,.5)" : hov ? "rgba(245,158,11,.6)" : "rgba(245,158,11,.3)"}`,
        color: done ? "#6ee7b7" : "#fcd34d",
        borderRadius: 10,
        padding: "7px 14px",
        cursor: "pointer",
        fontSize: 12,
        fontWeight: 700,
        fontFamily: "inherit",
        display: "flex",
        alignItems: "center",
        gap: 6,
        transition: "all .2s",
        position: "relative",
      }}
    >
      <span style={{ fontSize: 14 }}>{done ? "✅" : "🛡️"}</span>
      {done ? "Backup salvo!" : "Backup"}
      {hasUnsaved && !done && (
        <span
          style={{
            position: "absolute",
            top: -4,
            right: -4,
            width: 9,
            height: 9,
            borderRadius: "50%",
            background: "#ef4444",
            border: "2px solid #0d0d14",
          }}
        />
      )}
    </button>
  );
}

